func (m *SystemMetaMutation) Fields() []string {
	fields := make([]string, 0, 2)
	if m.key != nil {
		fields = append(fields, systemmeta.FieldKey)
	}
	if m.value != nil {
		fields = append(fields, systemmeta.FieldValue)
	}
	return fields
}

